// Extract and prepare workflow for n8n API
const input = $input.item.json;

// The workflow should already be parsed by Code in JavaScript node
if (input.workflow) {
  return {
    json: {
      workflow: input.workflow,
      workflowJson: JSON.stringify(input.workflow),
      debug: input.debug || 'Workflow passed through'
    }
  };
}

// Fallback: If no workflow, return error info
const fallbackWorkflow = {
  name: "No Workflow Found",
  nodes: [{id:"t",name:"Manual Trigger",type:"n8n-nodes-base.manualTrigger",typeVersion:1,position:[240,300],parameters:{}}],
  connections: {},
  settings: {executionOrder:"v1"},
  staticData: null
};

return {
  json: {
    workflow: fallbackWorkflow,
    workflowJson: JSON.stringify(fallbackWorkflow),
    debug: 'No workflow in input',
    receivedKeys: Object.keys(input)
  }
};

const workflow = $('Clean JSON').item.json.workflow;

const errors = [];
const warnings = [];

if (!workflow.nodes || workflow.nodes.length === 0) {
  errors.push({ message: "Workflow has no nodes" });
}

const triggers = ['webhook', 'manualTrigger', 'scheduleTrigger', 'emailTrigger', 'chatTrigger', 'cronTrigger'];
const hasTrigger = workflow.nodes?.some(node => 
  triggers.some(t => node.type?.toLowerCase().includes(t.toLowerCase()))
);

if (!hasTrigger) {
  errors.push({ message: "No trigger node found - workflow needs a trigger to execute" });
}

const connectedNodes = new Set();
Object.values(workflow.connections || {}).forEach(conns => {
  Object.values(conns).forEach(outputs => {
    outputs.forEach(outputArray => {
      outputArray.forEach(conn => {
        if (conn.node) connectedNodes.add(conn.node);
      });
    });
  });
});

const disconnected = workflow.nodes?.filter(n => 
  !connectedNodes.has(n.name) && 
  !n.type?.toLowerCase().includes('trigger') &&
  !n.type?.toLowerCase().includes('stickynote') &&
  n.name !== workflow.nodes[0]?.name
);

if (disconnected?.length > 0) {
  warnings.push({ 
    message: `${disconnected.length} disconnected node(s): ${disconnected.map(n => n.name).join(', ')}`
  });
}

const fakeApiPatterns = [
  'api.google.com',
  'api.twitter.com', 
  'api.facebook.com',
  'graph.facebook.com',
  'api.instagram.com',
  'graph.instagram.com',
  'api.tiktok.com',
  'api.unsplash.com',
  'api.example.com',
  'example.com/api'
];

workflow.nodes?.forEach(node => {
  if (node.type?.includes('httpRequest')) {
    const url = node.parameters?.url || '';

    if (!url || url.trim() === '') {
      errors.push({ message: `Node "${node.name}" has empty URL` });
    }

    const fakeMatch = fakeApiPatterns.find(pattern => url.toLowerCase().includes(pattern));
    if (fakeMatch) {
      errors.push({ 
        message: `Node "${node.name}" uses invalid API URL (${fakeMatch}). Use n8n's native nodes or real API endpoints.`
      });
    }

    if (url.includes('placeholder') || url.includes('example') || url.includes('your-')) {
      errors.push({ 
        message: `Node "${node.name}" has placeholder URL that needs configuration: ${url}`
      });
    }
  }
});

const nodesNeedingCreds = ['openai', 'slack', 'gmail', 'googleSheets', 'twitter', 'discord'];
workflow.nodes?.forEach(node => {
  const needsCreds = nodesNeedingCreds.some(n => node.type?.toLowerCase().includes(n.toLowerCase()));
  if (needsCreds && !node.credentials) {
    warnings.push({ message: `Node "${node.name}" likely needs credentials configured` });
  }
});

const isValid = errors.length === 0;

return {
  json: {
    workflow: workflow,
    isValid: isValid,
    errors: errors,
    warnings: warnings,
    suggestions: errors.length > 0 ? ['Agent 3 will fix these issues'] : []
  }
};

