// Extract workflow JSON from Agent 2's output
const aiOutput = $input.item.json.output;

console.log('Raw AI Output:', aiOutput?.substring(0, 200));

if (!aiOutput) {
  throw new Error('Agent 2 returned no output');
}

let workflow;

// Try 1: Parse as JSON directly
try {
  workflow = typeof aiOutput === 'string' ? JSON.parse(aiOutput) : aiOutput;
  if (workflow.nodes && Array.isArray(workflow.nodes)) {
    console.log('✓ Parsed as direct JSON');
    return { json: { workflow: workflow, debug: 'Direct parse' } };
  }
} catch (e) {
  console.log('✗ Direct parse failed:', e.message);
}

// Try 2: Extract from markdown code blocks
const patterns = [
  /```json\s*\n?([\s\S]*?)\n?```/,
  /```\s*\n?([\s\S]*?)\n?```/,
  /\{[\s\S]*"nodes"[\s\S]*\}/
];

for (const pattern of patterns) {
  const match = String(aiOutput).match(pattern);
  if (match) {
    try {
      const jsonStr = match[1] || match[0];
      workflow = JSON.parse(jsonStr);
      if (workflow.nodes && Array.isArray(workflow.nodes)) {
        console.log('✓ Extracted from markdown');
        return { json: { workflow: workflow, debug: 'Markdown extract' } };
      }
    } catch (e) {
      console.log('✗ Markdown parse failed:', e.message);
      continue;
    }
  }
}

// Try 3: Find JSON object in text
const jsonMatch = String(aiOutput).match(/(\{[\s\S]*\})/);
if (jsonMatch) {
  try {
    workflow = JSON.parse(jsonMatch[1]);
    if (workflow.nodes && Array.isArray(workflow.nodes)) {
      console.log('✓ Extracted JSON from text');
      return { json: { workflow: workflow, debug: 'Text extract' } };
    }
  } catch (e) {
    console.log('✗ JSON from text failed:', e.message);
  }
}

// Failed - throw error with details
throw new Error(
  `Cannot parse Agent 2 output. First 500 chars: ${String(aiOutput).substring(0, 500)}`
);
